"use client"

import { useEffect, useRef, useState } from "react";
import { Message } from "@/stores/ChatStore";
import { useGetChat, useSendMessage } from "@/hooks/use-chat";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { SendHorizontal, User, Bot, Sparkles } from "lucide-react";
import { cn } from "@/lib/utils";
import { Spinner } from "@/components/ui/spinner";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { useVirtualizer } from "@tanstack/react-virtual";
import { useRouter } from "next/navigation";

interface ChatContainerProps {
    chatId: string;
}

export function ChatContainer({ chatId }: ChatContainerProps) {
    const chat = useGetChat(chatId);
    const sendMessageMutation = useSendMessage();
    const [inputValue, setInputValue] = useState("");
    const router = useRouter();

    // Ref for the scrollable container
    const parentRef = useRef<HTMLDivElement>(null);

    const messages = chat?.messages || [];

    // The virtualizer logic
    const rowVirtualizer = useVirtualizer({
        count: messages.length,
        getScrollElement: () => parentRef.current,
        estimateSize: () => 100, // Estimate height of a message
        overscan: 5,
    });

    // Auto-scroll to bottom when messages change
    useEffect(() => {
        if (messages.length > 0) {
            rowVirtualizer.scrollToIndex(messages.length - 1, { align: 'end', behavior: 'smooth' });
        }
    }, [messages.length, rowVirtualizer]);

    const handleSendMessage = () => {
        if (!inputValue.trim()) return;
        sendMessageMutation.mutate({ chatId, content: inputValue });
        setInputValue("");
    };

    if (!chat) {
        return (
            <div className="flex items-center justify-center h-full text-muted-foreground">
                Chat not found.
            </div>
        );
    }

    return (
        <div className="flex flex-col h-full bg-background relative overflow-hidden">
            {/* Thread Title Bar */}
            <header className="flex items-center justify-between px-6 py-3 border-b border-border/50 bg-background/80 backdrop-blur-md sticky top-0 z-20">
                <div className="flex items-center gap-3 min-w-0">
                    <div className="bg-primary/10 p-2 rounded-lg shrink-0">
                        <Sparkles className="size-4 text-primary" />
                    </div>
                    <div className="flex flex-col min-w-0">
                        <h1 className="text-sm font-semibold truncate">
                            {chat.title}
                        </h1>
                        <p className="text-[10px] text-muted-foreground">
                            {messages.length} messages
                        </p>
                    </div>
                </div>
                <div className="flex items-center gap-2">
                    <Button variant="ghost" size="icon" className="size-8 rounded-lg">
                        <User className="size-4" />
                    </Button>
                </div>
            </header>

            {/* Messages Area */}
            <div className="flex-1 min-h-0 relative">
                <div
                    ref={parentRef}
                    className="h-full w-full overflow-y-auto scrollbar-hide pt-8 pb-40"
                    style={{ contain: 'strict' }}
                >
                    <div className="max-w-3xl mx-auto px-4 relative">
                        {messages.length === 0 ? (
                            <div className="flex flex-col items-center justify-center h-[60vh] text-center space-y-4">
                                <div className="bg-primary/10 p-4 rounded-full">
                                    <Sparkles className="size-8 text-primary" />
                                </div>
                                <h2 className="text-2xl font-bold">How can I help you today?</h2>
                                <p className="text-muted-foreground max-w-sm">
                                    Ask me anything about our products, store locations, or order status.
                                </p>
                            </div>
                        ) : (
                            <div
                                style={{
                                    height: `${rowVirtualizer.getTotalSize()}px`,
                                    width: '100%',
                                    position: 'relative',
                                }}
                            >
                                {rowVirtualizer.getVirtualItems().map((virtualRow) => {
                                    const message = messages[virtualRow.index];
                                    return (
                                        <div
                                            key={virtualRow.key}
                                            data-index={virtualRow.index}
                                            ref={rowVirtualizer.measureElement}
                                            className="absolute top-0 left-0 w-full py-4"
                                            style={{
                                                transform: `translateY(${virtualRow.start}px)`,
                                            }}
                                        >
                                            <div
                                                className={cn(
                                                    "flex gap-4 group",
                                                    message.role === "user" ? "justify-end" : "justify-start"
                                                )}
                                            >
                                                {message.role === "assistant" && (
                                                    <Avatar className="size-8 bg-primary/10 shrink-0">
                                                        <AvatarFallback><Bot className="size-4" /></AvatarFallback>
                                                        <AvatarImage src="/bot-avatar.png" />
                                                    </Avatar>
                                                )}
                                                <div
                                                    className={cn(
                                                        "max-w-[85%] rounded-2xl px-4 py-3 text-sm transition-all duration-300",
                                                        message.role === "user"
                                                            ? "bg-primary text-primary-foreground rounded-tr-none shadow-md"
                                                            : message.content.startsWith("🚨")
                                                                ? "error-bubble rounded-tl-none ring-2 ring-destructive/20 shadow-lg"
                                                                : "bg-muted text-foreground rounded-tl-none shadow-sm"
                                                    )}
                                                >
                                                    <div className="prose prose-sm dark:prose-invert max-w-none break-words leading-relaxed overflow-hidden">
                                                        {message.content.startsWith("🚨") ? (
                                                            <div className="flex flex-col gap-1">
                                                                <div className="error-title">
                                                                    <span>Internal Server Error</span>
                                                                </div>
                                                                <ReactMarkdown remarkPlugins={[remarkGfm]}>
                                                                    {message.content.replace("🚨", "").trim()}
                                                                </ReactMarkdown>
                                                            </div>
                                                        ) : message.content === "" ? (
                                                            <div className="flex items-center gap-2 py-1">
                                                                <Spinner className="size-4 animate-spin" />
                                                                <span className="text-xs animate-pulse">Thinking...</span>
                                                            </div>
                                                        ) : (
                                                            <ReactMarkdown
                                                                remarkPlugins={[remarkGfm]}
                                                                components={{
                                                                    pre: ({ ...props }) => (
                                                                        <div className="overflow-auto my-2 w-full rounded-lg bg-black/10 dark:bg-white/5 p-3 text-xs border border-border/50 shadow-inner">
                                                                            <pre {...props} />
                                                                        </div>
                                                                    ),
                                                                    code: ({ ...props }) => {
                                                                        return <code className="bg-black/10 dark:bg-white/10 rounded px-1 font-mono text-[0.9em]" {...props} />;
                                                                    },
                                                                    ul: ({ ...props }) => <ul className="list-disc ml-4 my-2" {...props} />,
                                                                    ol: ({ ...props }) => <ol className="list-decimal ml-4 my-2" {...props} />,
                                                                    p: ({ ...props }) => <p className="mb-2 last:mb-0" {...props} />,
                                                                    h3: ({ ...props }) => <h3 className="text-base font-bold my-2" {...props} />,
                                                                }}
                                                            >
                                                                {message.content}
                                                            </ReactMarkdown>
                                                        )}
                                                    </div>
                                                    <div className={cn(
                                                        "text-[10px] mt-2 opacity-50 font-medium font-sans",
                                                        message.role === "user" ? "text-right" : "text-left"
                                                    )}>
                                                        {new Date(message.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                                    </div>
                                                </div>
                                                {message.role === "user" && (
                                                    <Avatar className="size-8 border bg-muted shrink-0">
                                                        <AvatarFallback><User className="size-4" /></AvatarFallback>
                                                    </Avatar>
                                                )}
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        )}
                    </div>
                </div>

                {/* Fixed Floating Input Area */}
                <div className="absolute bottom-0 left-0 right-0 z-10">
                    <div className="bg-gradient-to-t from-background via-background/95 to-transparent pt-12 pb-6 px-4">
                        <div className="max-w-3xl mx-auto relative group">
                            <div className="absolute -inset-1 bg-gradient-to-r from-primary/20 to-primary/10 rounded-2xl blur opacity-25 group-focus-within:opacity-100 transition duration-1000 group-hover:duration-200"></div>
                            <div className="relative flex items-center bg-background border rounded-2xl p-1.5 shadow-xl focus-within:ring-2 ring-primary/20 transition-all border-border/80">
                                <Input
                                    placeholder="Message AI Assistant..."
                                    className="border-none focus-visible:ring-0 focus-visible:ring-offset-0 bg-transparent text-base py-6 px-4 h-auto"
                                    value={inputValue}
                                    onChange={(e) => setInputValue(e.target.value)}
                                    onKeyDown={(e) => {
                                        if (e.key === "Enter" && !e.shiftKey) {
                                            e.preventDefault();
                                            handleSendMessage();
                                        }
                                    }}
                                />
                                <Button
                                    size="icon"
                                    className={cn(
                                        "size-10 rounded-xl transition-all",
                                        inputValue.trim() ? "bg-primary scale-100" : "bg-muted text-muted-foreground scale-90"
                                    )}
                                    disabled={!inputValue.trim()}
                                    onClick={handleSendMessage}
                                >
                                    <SendHorizontal className="size-5" />
                                </Button>
                            </div>
                            <p className="text-[10px] text-center mt-3 text-muted-foreground font-medium uppercase tracking-wider opacity-60">
                                Powered by LLM Chat Engine
                            </p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}
